it":"","ticks":[{"at":0,"label":"0"},{"at":4,"label":"4"},{"at":10,"label":"10"},{"at":15,"label":"?"}],"max":16},{"label":"Cost (FCFA)","unit":"","ticks":[{"at":0,"label":"0"},{"at":4,"label":"2 600"},{"at":10,"label":"6 500"},{"at":15,"label":"9 750"}],"max":16}],"version":1}}}]},"e":"One litre costs 2 600 ÷ 4 = 650 FCFA, so 9 750 FCFA buys 9 750 ÷ 650 = 15 litres.","m":1,"df":"medium","tp":"Direct proportion","st":"double number line","cfg":{"question_number":22,"paper_question_key":22,"paper_section":"A","myp_criterion":"A","criterion_label":"Criterion A — Knowing and understanding","criterion_title":"Knowing and understanding","difficulty_level":"intermediate","marks":1,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":23,"t":"single_choice","p":"Which set is shaded in the Venn diagram?\n\n[Figure: Shaded region]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which set is shaded in the Venn diagram?"}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"venn2","title":"Shaded region","venn":{"leftLabel":"A","rightLabel":"B","leftOnly":"","both":"","rightOnly":"shaded","outside":""},"version":1}}}]},"e":"Only the part of B that lies outside A is shaded, which is $A'' \\cap B$ (B only).","m":1,"df":"medium","tp":"Set theory","st":"shaded region of a Venn diagram","cfg":{"question_number":23,"paper_question_key":23,"paper_section":"A","myp_criterion":"C","criterion_label":"Criterion C — Communicating","criterion_title":"Communicating","difficulty_level":"intermediate","marks":1,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":24,"t":"single_choice","p":"In a group of 40 tourists, 26 speak French, 19 speak English and 9 speak both. How many speak neither language?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a group of 40 tourists, 26 speak French, 19 speak English and 9 speak both. How many speak neither language?"}]}]},"e":"At least one language: 26 + 19 − 9 = 36. Neither: 40 − 36 = 4.","m":1,"df":"medium","tp":"Set theory","st":"inclusion–exclusion with an outside region","cfg":{"question_number":24,"paper_question_key":24,"paper_section":"A","myp_criterion":"A","criterion_label":"Criterion A — Knowing and understanding","criterion_title":"Knowing and understanding","difficulty_level":"intermediate","marks":1,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":25,"t":"single_choice","p":"The fair spinner has 8 equal sectors. It is spun once. What is the probability of an odd number?\n\n[Figure: Spinner sectors, clockwise from the top]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The fair spinner has 8 equal sectors. It is spun once. What is the probability of an odd number?"}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Spinner sectors, clockwise from the top","columns":["Sector","1","2","3","4","5","6","7","8"],"rows":[["Number","5","1","3","4","3","2","1","3"]],"version":1}}}]},"e":"Six of the eight sectors hold an odd number, so $P(\\text{odd}) = \\frac{6}{8} = \\frac{3}{4}$.","m":1,"df":"medium","tp":"Probability","st":"probability from a fair spinner","cfg":{"question_number":25,"paper_question_key":25,"paper_section":"A","myp_criterion":"A","criterion_label":"Criterion A — Knowing and understanding","criterion_title":"Knowing and understanding","difficulty_level":"intermediate","marks":1,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":26,"t":"single_choice","p":"A factory knows that 4 % of its phone chargers are faulty. In a delivery of 1 500 chargers, how many are expected to work?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A factory knows that 4 % of its phone chargers are faulty. In a delivery of 1 500 chargers, how many are expected to work?"}]}]},"e":"96 % work, so the expected number is 0.96 × 1 500 = 1 440. Option A is the number expected to be faulty.","m":1,"df":"medium","tp":"Probability","st":"expected frequency in a real-life context","cfg":{"question_number":26,"paper_question_key":26,"paper_section":"A","myp_criterion":"D","criterion_label":"Criterion D — Applying mathematics in real-life contexts","criterion_title":"Applying mathematics in real-life contexts","difficulty_level":"intermediate","marks":1,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":27,"t":"single_choice","p":"A bag holds 20 marbles, as the bar chart shows. One marble is picked at random.\n\n[Figure: Marbles in the bag]\nP(red) — write the letter of the correct value.\n\n[Figure: table]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A bag holds 20 marbles, as the bar chart shows. One marble is picked at random."}]},{"type":"statsBlock","attrs":{"spec":{"version":1,"chart":"bar_chart","title":"Marbles in the bag","xLabel":"Colour","yLabel":"Number of marbles","values":[],"categories":[{"id":"c0","label":"Red","value":8},{"id":"c1","label":"Yellow","value":5},{"id":"c2","label":"Green","value":4},{"id":"c3","label":"Blue","value":3}],"binWidth":null,"showSummary":false,"dataMode":"raw"}}},{"type":"paragraph","content":[{"type":"text","text":"P(red) — write the letter of the correct value."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"","columns":["P","Q","R","S","T","U"],"rows":[["0","0.2","40 %","0.75","0.25","1"]],"version":1}}}]},"e":"8 of the 20 marbles are red: $\\frac{8}{20} = 0.4 = 40\\ \\%$.","m":1,"df":"medium","tp":"Probability","st":"matching a probability to its value","cfg":{"question_number":27,"paper_question_key":27,"paper_section":"A","myp_criterion":"C","criterion_label":"Criterion C — Communicating","criterion_title":"Communicating","difficulty_level":"intermediate","marks":1,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":28,"t":"single_choice","p":"A bag holds 20 marbles, as the bar chart shows. One marble is picked at random.\n\n[Figure: Marbles in the bag]\nP(not yellow) — write the letter of the correct value.\n\n[Figure: table]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A bag holds 20 marbles, as the bar chart shows. One marble is picked at random."}]},{"type":"statsBlock","attrs":{"spec":{"version":1,"chart":"bar_chart","title":"Marbles in the bag","xLabel":"Colour","yLabel":"Number of marbles","values":[],"categories":[{"id":"c0","label":"Red","value":8},{"id":"c1","label":"Yellow","value":5},{"id":"c2","label":"Green","value":4},{"id":"c3","label":"Blue","value":3}],"binWidth":null,"showSummary":false,"dataMode":"raw"}}},{"type":"paragraph","content":[{"type":"text","text":"P(not yellow) — write the letter of the correct value."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"","columns":["P","Q","R","S","T","U"],"rows":[["0","0.2","40 %","0.75","0.25","1"]],"version":1}}}]},"e":"15 of the 20 marbles are not yellow: $\\frac{15}{20} = 0.75$.","m":1,"df":"medium","tp":"Probability","st":"matching a probability to its value","cfg":{"question_number":28,"paper_question_key":28,"paper_section":"A","myp_criterion":"C","criterion_label":"Criterion C — Communicating","criterion_title":"Communicating","difficulty_level":"intermediate","marks":1,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":29,"t":"single_choice","p":"A bag holds 20 marbles, as the bar chart shows. One marble is picked at random.\n\n[Figure: Marbles in the bag]\nP(green) — write the letter of the correct value.\n\n[Figure: table]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A bag holds 20 marbles, as the bar chart shows. One marble is picked at random."}]},{"type":"statsBlock","attrs":{"spec":{"version":1,"chart":"bar_chart","title":"Marbles in the bag","xLabel":"Colour","yLabel":"Number of marbles","values":[],"categories":[{"id":"c0","label":"Red","value":8},{"id":"c1","label":"Yellow","value":5},{"id":"c2","label":"Green","value":4},{"id":"c3","label":"Blue","value":3}],"binWidth":null,"showSummary":false,"dataMode":"raw"}}},{"type":"paragraph","content":[{"type":"text","text":"P(green) — write the letter of the correct value."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"","columns":["P","Q","R","S","T","U"],"rows":[["0","0.2","40 %","0.75","0.25","1"]],"version":1}}}]},"e":"4 of the 20 marbles are green: $\\frac{4}{20} = 0.2$.","m":1,"df":"medium","tp":"Probability","st":"matching a probability to its value","cfg":{"question_number":29,"paper_question_key":29,"paper_section":"A","myp_criterion":"C","criterion_label":"Criterion C — Communicating","criterion_title":"Communicating","difficulty_level":"intermediate","marks":1,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":30,"t":"single_choice","p":"A bag holds 20 marbles, as the bar chart shows. One marble is picked at random.\n\n[Figure: Marbles in the bag]\nP(purple) — write the letter of the correct value.\n\n[Figure: table]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A bag holds 20 marbles, as the bar chart shows. One marble is picked at random."}]},{"type":"statsBlock","attrs":{"spec":{"version":1,"chart":"bar_chart","title":"Marbles in the bag","xLabel":"Colour","yLabel":"Number of marbles","values":[],"categories":[{"id":"c0","label":"Red","value":8},{"id":"c1","label":"Yellow","value":5},{"id":"c2","label":"Green","value":4},{"id":"c3","label":"Blue","value":3}],"binWidth":null,"showSummary":false,"dataMode":"raw"}}},{"type":"paragraph","content":[{"type":"text","text":"P(purple) — write the letter of the correct value."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"","columns":["P","Q","R","S","T","U"],"rows":[["0","0.2","40 %","0.75","0.25","1"]],"version":1}}}]},"e":"There is no purple marble in the bag, so the probability is 0.","m":1,"df":"medium","tp":"Probability","st":"matching a probability to its value","cfg":{"question_number":30,"paper_question_key":30,"paper_section":"A","myp_criterion":"C","criterion_label":"Criterion C — Communicating","criterion_title":"Communicating","difficulty_level":"intermediate","marks":1,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":31,"t":"single_choice","p":"The ratio of boys to girls in a choir is $4 : 5$. There are 12 more girls than boys. How many singers are in the choir?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The ratio of boys to girls in a choir is "},{"type":"mathInline","attrs":{"latex":"4 : 5"}},{"type":"text","text":". There are 12 more girls than boys. How many singers are in the choir?"}]}]},"e":"One ratio part is 12 (the difference 5 − 4 = 1 part). Total parts = 9, so the choir has 9 × 12 = 108 singers.","m":2,"df":"hard","tp":"Ratio and proportion","st":"ratio with a difference","cfg":{"question_number":31,"paper_question_key":31,"paper_section":"A","myp_criterion":"A","criterion_label":"Criterion A — Knowing and understanding","criterion_title":"Knowing and understanding","difficulty_level":"challenge","marks":2,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":32,"t":"single_choice","p":"A shop mixes peanuts and cashew nuts in the ratio $5 : 3$ by mass. Peanuts cost 1 200 FCFA per kg and cashew nuts 4 000 FCFA per kg. What do the nuts in 4 kg of the mixture cost?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A shop mixes peanuts and cashew nuts in the ratio "},{"type":"mathInline","attrs":{"latex":"5 : 3"}},{"type":"text","text":" by mass. Peanuts cost 1 200 FCFA per kg and cashew nuts 4 000 FCFA per kg. What do the nuts in 4 kg of the mixture cost?"}]}]},"e":"8 parts → 4 kg, so one part is 0.5 kg: 2.5 kg peanuts and 1.5 kg cashews. Cost = 2.5 × 1 200 + 1.5 × 4 000 = 3 000 + 6 000 = 9 000 FCFA for the 4 kg mixture.","m":2,"df":"hard","tp":"Ratio and proportion","st":"ratio and cost in a real-life context","cfg":{"question_number":32,"paper_question_key":32,"paper_section":"A","myp_criterion":"D","criterion_label":"Criterion D — Applying mathematics in real-life contexts","criterion_title":"Applying mathematics in real-life contexts","difficulty_level":"challenge","marks":2,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":33,"t":"single_choice","p":"One machine fills 180 bottles in 4 minutes. A newer machine fills 250 bottles in 5 minutes. How many more bottles does the newer machine fill in 1 hour?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One machine fills 180 bottles in 4 minutes. A newer machine fills 250 bottles in 5 minutes. How many more bottles does the newer machine fill in 1 hour?"}]}]},"e":"Older: 180 ÷ 4 × 60 = 2 700 per hour. Newer: 250 ÷ 5 × 60 = 3 000 per hour. Difference = 300 bottles.","m":2,"df":"hard","tp":"Rate","st":"comparing two rates over an hour","cfg":{"question_number":33,"paper_question_key":33,"paper_section":"A","myp_criterion":"D","criterion_label":"Criterion D — Applying mathematics in real-life contexts","criterion_title":"Applying mathematics in real-life contexts","difficulty_level":"challenge","marks":2,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":34,"t":"single_choice","p":"In the table, $y$ is directly proportional to $x$. What is the value of $a + b$?\n\n[Figure: table]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In the table, "},{"type":"mathInline","attrs":{"latex":"y"}},{"type":"text","text":" is directly proportional to "},{"type":"mathInline","attrs":{"latex":"x"}},{"type":"text","text":". What is the value of "},{"type":"mathInline","attrs":{"latex":"a + b"}},{"type":"text","text":"?"}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"","columns":["$x$","$x$","6","15","$b$"],"rows":[["$y$","$y$","$a$","20","36"]],"version":1}}}]},"e":"From 15 → 20 the multiplier is 4/3, so $a = 6 \\times \\frac{4}{3} = 8$ and $b = 36 \\div \\frac{4}{3} = 27$. Hence $a + b = 35$.","m":2,"df":"hard","tp":"Direct proportion","st":"proportionality table","cfg":{"question_number":34,"paper_question_key":34,"paper_section":"A","myp_criterion":"B","criterion_label":"Criterion B — Investigating patterns","criterion_title":"Investigating patterns","difficulty_level":"challenge","marks":2,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":35,"t":"single_choice","p":"On a map, 4 cm represents a real distance of 10 km. What is the scale of the map?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On a map, 4 cm represents a real distance of 10 km. What is the scale of the map?"}]}]},"e":"10 km = 1 000 000 cm, so 4 cm represents 1 000 000 cm and 1 cm represents 250 000 cm. The scale is 1 : 250 000.","m":2,"df":"hard","tp":"Scale drawing","st":"finding a map scale","cfg":{"question_number":35,"paper_question_key":35,"paper_section":"A","myp_criterion":"D","criterion_label":"Criterion D — Applying mathematics in real-life contexts","criterion_title":"Applying mathematics in real-life contexts","difficulty_level":"challenge","marks":2,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":36,"t":"single_choice","p":"$\\xi = \\{1, 2, 3, \\ldots, 20\\}$, $M = \\{\\text{multiples of 4}\\}$ and $F = \\{\\text{factors of 20}\\}$. What is $n((M \\cup F)'')$?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"mathInline","attrs":{"latex":"\\xi = \\{1, 2, 3, \\ldots, 20\\}"}},{"type":"text","text":", "},{"type":"mathInline","attrs":{"latex":"M = \\{\\text{multiples of 4}\\}"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"F = \\{\\text{factors of 20}\\}"}},{"type":"text","text":". What is "},{"type":"mathInline","attrs":{"latex":"n((M \\cup F)'')"}},{"type":"text","text":"?"}]}]},"e":"$M = \\{4, 8, 12, 16, 20\\}$ and $F = \\{1, 2, 4, 5, 10, 20\\}$, so $M \\cup F = \\{1, 2, 4, 5, 8, 10, 12, 16, 20\\}$, which has 9 elements. $n((M \\cup F)'') = 20 - 9 = 11$.","m":2,"df":"hard","tp":"Set theory","st":"complement of a union","cfg":{"question_number":36,"paper_question_key":36,"paper_section":"A","myp_criterion":"A","criterion_label":"Criterion A — Knowing and understanding","criterion_title":"Knowing and understanding","difficulty_level":"challenge","marks":2,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":37,"t":"single_choice","p":"A workshop has 38 workers. The Venn diagram shows how many own a bicycle (B) and a motorbike (M). How many own exactly one of the two?\n\n[Figure: venn2]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A workshop has 38 workers. The Venn diagram shows how many own a bicycle (B) and a motorbike (M). How many own exactly one of the two?"}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"venn2","title":"","venn":{"leftLabel":"B","rightLabel":"M","leftOnly":"$x + 5$","both":"$x$","rightOnly":"$2x - 1$","outside":"6","universalLabel":"ξ"},"version":1}}}]},"e":"$(x + 5) + x + (2x - 1) + 6 = 38$, so $4x + 10 = 38$ and $x = 7$. Exactly one vehicle: $(x + 5) + (2x - 1) = 12 + 13 = 25$.","m":2,"df":"hard","tp":"Set theory","st":"Venn diagram with algebra","cfg":{"question_number":37,"paper_question_key":37,"paper_section":"A","myp_criterion":"A","criterion_label":"Criterion A — Knowing and understanding","criterion_title":"Knowing and understanding","difficulty_level":"challenge","marks":2,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":38,"t":"single_choice","p":"A bottle cap is tossed many times. The table shows how often it has landed top-up. Which is the best estimate of the probability that it lands top-up?\n\n[Figure: table]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A bottle cap is tossed many times. The table shows how often it has landed top-up. Which is the best estimate of the probability that it lands top-up?"}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"","columns":["Number of tosses","20","100","500","2 000"],"rows":[["Top-up","9","38","205","796"]],"version":1}}}]},"e":"The largest sample gives the best estimate: 796 ÷ 2 000 = 0.398, which is 0.40 to 2 d.p.","m":2,"df":"hard","tp":"Probability","st":"experimental probability from a table","cfg":{"question_number":38,"paper_question_key":38,"paper_section":"A","myp_criterion":"B","criterion_label":"Criterion B — Investigating patterns","criterion_title":"Investigating patterns","difficulty_level":"challenge","marks":2,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":39,"t":"single_choice","p":"A jar holds red and green sweets only. There are 26 green sweets, and for a sweet picked at random $P(\\text{red}) = 0.35$. How many sweets are in the jar?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A jar holds red and green sweets only. There are 26 green sweets, and for a sweet picked at random "},{"type":"mathInline","attrs":{"latex":"P(\\text{red}) = 0.35"}},{"type":"text","text":". How many sweets are in the jar?"}]}]},"e":"$P(\\text{green}) = 1 - 0.35 = 0.65$, so 0.65 × total = 26 and the total is 40 sweets.","m":2,"df":"hard","tp":"Probability","st":"finding a total from a probability","cfg":{"question_number":39,"paper_question_key":39,"paper_section":"A","myp_criterion":"A","criterion_label":"Criterion A — Knowing and understanding","criterion_title":"Knowing and understanding","difficulty_level":"challenge","marks":2,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":40,"t":"single_choice","p":"In a random sample of 80 pupils, 28 walk to school. The school has 1 240 pupils. Estimate how many pupils do not walk to school.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a random sample of 80 pupils, 28 walk to school. The school has 1 240 pupils. Estimate how many pupils do not walk to school."}]}]},"e":"The sample gives 80 − 28 = 52 pupils who do not walk, so the estimate is $\\frac{52}{80} \\times 1\\,240 = 806$.","m":2,"df":"hard","tp":"Probability","st":"estimating from a sample","cfg":{"question_number":40,"paper_question_key":40,"paper_section":"A","myp_criterion":"D","criterion_label":"Criterion D — Applying mathematics in real-life contexts","criterion_title":"Applying mathematics in real-life contexts","difficulty_level":"challenge","marks":2,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp2-term1-summative-b-2026"}},{"n":41,"t":"open_ended","p":"Primes and multiples [8 marks]  $\\xi = \\{1, 2, 3, \\ldots, 15\\}$, $P = \\{\\text{prime numbers}\\}$ and $T = \\{\\text{multiples of 3}\\}$.\n(a) List the elements of P and the elements of T. [2]\n(b) Find $P \\cap T$ and $n(P \\cup T)$. [3]\n(c) A number is chosen at random from $\\xi$. Find, in its simplest form, the probability that it is in neither P nor T. [3]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Primes and multiples [8 marks]  "},{"type":"mathInline","attrs":{"latex":"\\xi = \\{1, 2, 3, \\ldots, 15\\}"}},{"type":"text","text":", "},{"type":"mathInline","attrs":{"latex":"P = \\{\\text{prime numbers}\\}"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"T = \\{\\text{multiples of 3}\\}"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) List the elements of P and the elements of T. [2]"}]},{"type":"paragraph","content":[{"type":"text","text":"(b) Find "},{"type":"mathInline","attrs":{"latex":"P \\cap T"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"n(P \\cup T)"}},{"type":"text","text":". [3]"}]},{"type":"paragraph","content":[{"type":"text","text":"(c) A number is chosen at random from "},{"type":"mathInline","attrs":{"latex":"\\xi"}},{"type":"text","text":". Find, in its simplest form, the probability that it is in neither P nor T. [3]"}]}]},"e":"$P = \\{2, 3, 5, 7, 11, 13\\}$ and $T = \\{3, 6, 9, 12, 15\\}$. $P \\cap T = \\{3\\}$ and $n(P \\cup T) = 6 + 5 - 1 = 10$. Neither: $15 - 10 = 5$ numbers, so the probability is $\\frac{5}{15} = \\frac{1}{3}$.","m":8,"df":"medium","tp":"Set theory","st":"primes and multiples","cfg":{"question_number":41,"paper_question_key":41,"paper_section":"B","myp_criterion":"A","criterion_label":"Criterion A — Knowing and understanding","criterion_title":"Knowing and understanding","difficulty_level":"intermediate","marks":8,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","marking_breakdown":[{"label":"(a)","marks":2,"focus":"Lists of P and T"},{"label":"(b)","marks":3,"focus":"Intersection and union"},{"label":"(c)","marks":3,"focus":"Probability of neither"}],"response_guidance":"Show every set listing and every step of the probability calculation.","response_tools":["rich_text","math","venn"],"tool_labels":["rich_text","math","venn"],"source":"myp2-term1-summative-b-2026"}},{"n":42,"t":"open_ended","p":"Counting a union [12 marks] The table gives the numbers of elements for three pairs of sets A and B.\n\n[Figure: table]\n(a) $A = \\{2, 4, 6, 8, 10, 12\\}$ and $B = \\{3, 6, 9, 12\\}$. Find $n(A)$, $n(B)$, $n(A \\cap B)$ and $n(A \\cup B)$. [3]\n(b) Describe how $n(A \\cup B)$ can be found from the other three numbers. Predict $n(A \\cup B)$ when $n(A) = 20$, $n(B) = 15$ and $n(A \\cap B) = 8$. [2]\n(c) Write a general rule for $n(A \\cup B)$. Verify it using your answers to (a). [3]\n(d) Use your rule to find $n(A \\cap B)$ when $n(A) = 18$, $n(B) = 11$ and $n(A \\cup B) = 23$, and to decide whether $n(A) = 9$, $n(B) = 5$ and $n(A \\cup B) = 15$ is possible. [4]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Counting a union [12 marks] The table gives the numbers of elements for three pairs of sets A and B."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"","columns":["Pair of sets","n(A)","n(B)","n(A ∩ B)","n(A ∪ B)"],"rows":[["Pair 1","4","3","2","5"],["Pair 2","7","4","4","7"],["Pair 3","5","8","0","13"]],"version":1}}},{"type":"paragraph","content":[{"type":"text","text":"(a) "},{"type":"mathInline","attrs":{"latex":"A = \\{2, 4, 6, 8, 10, 12\\}"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"B = \\{3, 6, 9, 12\\}"}},{"type":"text","text":". Find "},{"type":"mathInline","attrs":{"latex":"n(A)"}},{"type":"text","text":", "},{"type":"mathInline","attrs":{"latex":"n(B)"}},{"type":"text","text":", "},{"type":"mathInline","attrs":{"latex":"n(A \\cap B)"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"n(A \\cup B)"}},{"type":"text","text":". [3]"}]},{"type":"paragraph","content":[{"type":"text","text":"(b) Describe how "},{"type":"mathInline","attrs":{"latex":"n(A \\cup B)"}},{"type":"text","text":" can be found from the other three numbers. Predict "},{"type":"mathInline","attrs":{"latex":"n(A \\cup B)"}},{"type":"text","text":" when "},{"type":"mathInline","attrs":{"latex":"n(A) = 20"}},{"type":"text","text":", "},{"type":"mathInline","attrs":{"latex":"n(B) = 15"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"n(A \\cap B) = 8"}},{"type":"text","text":". [2]"}]},{"type":"paragraph","content":[{"type":"text","text":"(c) Write a general rule for "},{"type":"mathInline","attrs":{"latex":"n(A \\cup B)"}},{"type":"text","text":". Verify it using your answers to (a). [3]"}]},{"type":"paragraph","content":[{"type":"text","text":"(d) Use your rule to find "},{"type":"mathInline","attrs":{"latex":"n(A \\cap B)"}},{"type":"text","text":" when "},{"type":"mathInline","attrs":{"latex":"n(A) = 18"}},{"type":"text","text":", "},{"type":"mathInline","attrs":{"latex":"n(B) = 11"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"n(A \\cup B) = 23"}},{"type":"text","text":", and to decide whether "},{"type":"mathInline","attrs":{"latex":"n(A) = 9"}},{"type":"text","text":", "},{"type":"mathInline","attrs":{"latex":"n(B) = 5"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"n(A \\cup B) = 15"}},{"type":"text","text":" is possible. [4]"}]}]},"e":"(a) $n(A) = 6$, $n(B) = 4$, $n(A \\cap B) = \\{6, 12\\} = 2$, $n(A \\cup B) = 8$. (b) Add $n(A)$ and $n(B)$ then subtract the overlap: $20 + 15 - 8 = 27$. (c) $n(A \\cup B) = n(A) + n(B) - n(A \\cap B)$; check: $6 + 4 - 2 = 8$. (d) $n(A \\cap B) = 18 + 11 - 23 = 6$. For the second case $9 + 5 = 14 < 15$, so it is impossible — the union cannot exceed the sum of the two sets.","m":12,"df":"hard","tp":"Set theory","st":"counting a union","cfg":{"question_number":42,"paper_question_key":42,"paper_section":"B","myp_criterion":"B","criterion_label":"Criterion B — Investigating patterns","criterion_title":"Investigating patterns","difficulty_level":"challenge","marks":12,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","marking_breakdown":[{"label":"(a)","marks":3,"focus":"Counts for the given sets"},{"label":"(b)","marks":2,"focus":"Description and prediction"},{"label":"(c)","marks":3,"focus":"General rule and verification"},{"label":"(d)","marks":4,"focus":"Applying the rule in reverse"}],"response_guidance":"Use the three rows of the table as your evidence, then state and verify a general rule.","response_tools":["rich_text","math","table","data_table"],"tool_labels":["rich_text","math","table","data_table"],"source":"myp2-term1-summative-b-2026"}},{"n":43,"t":"open_ended","p":"Photo prints [10 marks] The graph shows the cost of printing photos at two shops, A and B.\n\n[Figure: Cost of photo prints]\n(a) Use the graph to find the cost of 12 photos at each shop. [2]\n(b) For each shop, state the price of one photo and write a formula for the cost $C$ (in FCFA) of $n$ photos. [3]\n(c) Give two features of the graph which show that the cost is directly proportional to the number of photos. [2]\n(d) Kévin has 2 400 FCFA. How many more photos can he print at shop B than at shop A? Show your reasoning clearly. [3]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Photo prints [10 marks] The graph shows the cost of printing photos at two shops, A and B."}]},{"type":"graphBlock","attrs":{"spec":{"version":1,"domain":{"xMin":0,"xMax":20,"yMin":0,"yMax":3000,"gridStep":null,"showGrid":true,"showAxes":true,"showCoordinates":false,"showLegend":true,"showIntersections":false,"equalScale":false},"functions":[{"id":"a","expression":"150x","color":"#0a5c36","style":"solid","width":2,"label":"Shop A","from":0,"to":20,"visible":true},{"id":"b","expression":"100x","color":"#b45309","style":"solid","width":2,"label":"Shop B","from":0,"to":20,"visible":true}],"points":[],"segments":[],"annotations":[],"strokes":[],"regions":[],"xLabel":"Number of photos","yLabel":"Cost (FCFA)","title":"Cost of photo prints"}}},{"type":"paragraph","content":[{"type":"text","text":"(a) Use the graph to find the cost of 12 photos at each shop. [2]"}]},{"type":"paragraph","content":[{"type":"text","text":"(b) For each shop, state the price of one photo and write a formula for the cost "},{"type":"mathInline","attrs":{"latex":"C"}},{"type":"text","text":" (in FCFA) of "},{"type":"mathInline","attrs":{"latex":"n"}},{"type":"text","text":" photos. [3]"}]},{"type":"paragraph","content":[{"type":"text","text":"(c) Give two features of the graph which show that the cost is directly proportional to the number of photos. [2]"}]},{"type":"paragraph","content":[{"type":"text","text":"(d) Kévin has 2 400 FCFA. How many more photos can he print at shop B than at shop A? Show your reasoning clearly. [3]"}]}]},"e":"(a) Shop A: 1 800 FCFA; shop B: 1 200 FCFA. (b) Shop A: 150 FCFA per photo, $C = 150n$; shop B: 100 FCFA per photo, $C = 100n$. (c) Both graphs are straight lines and both pass through the origin. (d) At shop A, 2 400 ÷ 150 = 16 photos; at shop B, 2 400 ÷ 100 = 24 photos, so 8 more photos at shop B.","m":10,"df":"medium","tp":"Direct proportion","st":"photo prints","cfg":{"question_number":43,"paper_question_key":43,"paper_section":"B","myp_criterion":"C","criterion_label":"Criterion C — Communicating","criterion_title":"Communicating","difficulty_level":"intermediate","marks":10,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","marking_breakdown":[{"label":"(a)","marks":2,"focus":"Reading the graph"},{"label":"(b)","marks":3,"focus":"Unit price and formula"},{"label":"(c)","marks":2,"focus":"Features of proportionality"},{"label":"(d)","marks":3,"focus":"Comparison with reasoning"}],"response_guidance":"Read values from the graph, then justify the features you identify.","response_tools":["rich_text","math","graph","table"],"tool_labels":["rich_text","math","graph","table"],"source":"myp2-term1-summative-b-2026"}},{"n":44,"t":"open_ended","p":"The prize wheel [8 marks] At a school fair a wheel has 12 equal sectors: 1 star prize (★), 3 small prizes (P) and 8 with no prize. Each player spins once.\n\n[Figure: shape_pattern]\n(a) Write the probability of winning a small prize as a fraction in its simplest form, a decimal and a percentage. [2]\n(b) Find the probability that a player wins a prize. Explain how this gives the probability of winning no prize. [2]\n(c) 300 people play. The organisers have 20 star prizes and 80 small prizes. Write a short report: are these enough? Use the term expected number and explain why the organisers cannot be certain. [4]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The prize wheel [8 marks] At a school fair a wheel has 12 equal sectors: 1 star prize (★), 3 small prizes (P) and 8 with no prize. Each player spins once."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"shape_pattern","title":"","patterns":[{"label":"★ star prize","squares":1,"dots":0},{"label":"P small prize","squares":3,"dots":0},{"label":"no prize","squares":8,"dots":0}],"version":1}}},{"type":"paragraph","content":[{"type":"text","text":"(a) Write the probability of winning a small prize as a fraction in its simplest form, a decimal and a percentage. [2]"}]},{"type":"paragraph","content":[{"type":"text","text":"(b) Find the probability that a player wins a prize. Explain how this gives the probability of winning no prize. [2]"}]},{"type":"paragraph","content":[{"type":"text","text":"(c) 300 people play. The organisers have 20 star prizes and 80 small prizes. Write a short report: are these enough? Use the term expected number and explain why the organisers cannot be certain. [4]"}]}]},"e":"(a) $\\frac{3}{12} = \\frac{1}{4} = 0.25 = 25\\ \\%$. (b) $P(\\text{prize}) = \\frac{4}{12} = \\frac{1}{3}$, so $P(\\text{no prize}) = 1 - \\frac{1}{3} = \\frac{2}{3}$. (c) Expected star prizes = $300 \\times \\frac{1}{12} = 25$ and expected small prizes = $300 \\times \\frac{1}{4} = 75$, so 20 star prizes are below the expected number while 80 small prizes are enough. The organisers cannot be certain because expectation is an average over many fairs — chance variation means any single fair can need more (or fewer).","m":8,"df":"medium","tp":"Probability","st":"the prize wheel","cfg":{"question_number":44,"paper_question_key":44,"paper_section":"B","myp_criterion":"C","criterion_label":"Criterion C — Communicating","criterion_title":"Communicating","difficulty_level":"intermediate","marks":8,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","marking_breakdown":[{"label":"(a)","marks":2,"focus":"Three representations"},{"label":"(b)","marks":2,"focus":"Winning a prize and its complement"},{"label":"(c)","marks":4,"focus":"Report using expected number"}],"response_guidance":"Give the fraction, the decimal and the percentage, then write your report in sentences.","response_tools":["rich_text","math","table"],"tool_labels":["rich_text","math","table"],"source":"myp2-term1-summative-b-2026"}},{"n":45,"t":"open_ended","p":"Bissap for a party [12 marks] Mrs Adjovi makes bissap for 54 guests by mixing syrup and water in the ratio $2 : 7$. Each guest receives one 250 mL glass. The shop prices are shown.\n\n[Figure: table]\n(a) How many litres of bissap does she need? [2]\n(b) Find the volume of syrup and the volume of water she needs. [3]\n(c) Which bottle of syrup is the better value? Find the lowest cost of the syrup she needs. [3]\n(d) Her budget is 9 000 FCFA. Is it enough for the syrup and the water? Justify your answer and state one assumption you have made. [4]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bissap for a party [12 marks] Mrs Adjovi makes bissap for 54 guests by mixing syrup and water in the ratio "},{"type":"mathInline","attrs":{"latex":"2 : 7"}},{"type":"text","text":". Each guest receives one 250 mL glass. The shop prices are shown."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"","columns":["Syrup 750 mL","Syrup 1.5 L","Water 1.5 L"],"rows":[["1 800 FCFA","3 300 FCFA","300 FCFA"]],"version":1}}},{"type":"paragraph","content":[{"type":"text","text":"(a) How many litres of bissap does she need? [2]"}]},{"type":"paragraph","content":[{"type":"text","text":"(b) Find the volume of syrup and the volume of water she needs. [3]"}]},{"type":"paragraph","content":[{"type":"text","text":"(c) Which bottle of syrup is the better value? Find the lowest cost of the syrup she needs. [3]"}]},{"type":"paragraph","content":[{"type":"text","text":"(d) Her budget is 9 000 FCFA. Is it enough for the syrup and the water? Justify your answer and state one assumption you have made. [4]"}]}]},"e":"(a) 54 × 250 mL = 13 500 mL = 13.5 L. (b) 9 parts → 13.5 L, so one part is 1.5 L: syrup = 3 L and water = 10.5 L. (c) The 750 mL bottle costs 1 800 ÷ 0.75 = 2 400 FCFA per litre and the 1.5 L bottle costs 3 300 ÷ 1.5 = 2 200 FCFA per litre, so the 1.5 L bottle is better value; 3 L costs 2 × 3 300 = 6 600 FCFA. (d) Water: 10.5 L ÷ 1.5 L = 7 bottles = 2 100 FCFA, giving 8 700 FCFA in total, which is within the 9 000 FCFA budget. Assumption: bottles must be bought whole, so 7 water bottles and 2 syrup bottles are purchased.","m":12,"df":"hard","tp":"Ratio and proportion","st":"bissap for a party","cfg":{"question_number":45,"paper_question_key":45,"paper_section":"B","myp_criterion":"D","criterion_label":"Criterion D — Applying mathematics in real-life contexts","criterion_title":"Applying mathematics in real-life contexts","difficulty_level":"challenge","marks":12,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","marking_breakdown":[{"label":"(a)","marks":2,"focus":"Total volume"},{"label":"(b)","marks":3,"focus":"Ratio split"},{"label":"(c)","marks":3,"focus":"Best value and lowest cost"},{"label":"(d)","marks":4,"focus":"Budget check with an assumption"}],"response_guidance":"Show the total volume, the ratio split, the value comparison and a budget check with your assumption stated.","response_tools":["rich_text","math","table","data_table"],"tool_labels":["rich_text","math","table","data_table"],"source":"myp2-term1-summative-b-2026"}}]'::jsonb) as x
